/**
 * Levenshtein distance algorithm
 * Calculates the minimum number of single-character edits
 * (insertions, deletions, or substitutions) required to change one string into another.
 */
function levenshteinDistance(str1, str2) {
  const m = str1.length;
  const n = str2.length;

  // Create a 2D array for dynamic programming
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  // Base cases: distance from empty string
  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  // Fill in the rest of the matrix
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (str1[i - 1] === str2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = 1 + Math.min(
          dp[i - 1][j],      // deletion
          dp[i][j - 1],      // insertion
          dp[i - 1][j - 1]   // substitution
        );
      }
    }
  }

  return dp[m][n];
}

/**
 * Create a debug helper for KnockoutJS template binding errors.
 * @param {Object} viewModel - A KnockoutJS-style ViewModel object
 * @returns {Object} Debug helper with diagnoseMissingProperty method
 */
function createDebugHelper(viewModel) {
  return {
    /**
     * Diagnose a missing property in a KnockoutJS binding.
     * @param {string} propertyName - The name of the property that failed to bind
     * @returns {Object} Diagnosis result with error details and suggestions
     */
    diagnoseMissingProperty(propertyName) {
      // Get sorted list of available properties on the ViewModel
      const availableProperties = Object.keys(viewModel).sort();

      // Find the closest matching property using Levenshtein distance
      let bestMatch = null;
      let minDistance = Infinity;

      for (const prop of availableProperties) {
        const distance = levenshteinDistance(propertyName, prop);

        if (distance <= 3) {
          if (distance < minDistance) {
            minDistance = distance;
            bestMatch = prop;
          } else if (distance === minDistance) {
            // If tied, pick the one that comes first alphabetically
            if (prop < bestMatch) {
              bestMatch = prop;
            }
          }
        }
      }

      return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties,
        suggestion: bestMatch
      };
    }
  };
}

module.exports = {
  levenshteinDistance,
  createDebugHelper
};
EOF"}

